function vertex(x: number, y: number): PathVertex {
  return {
    point: { x, y },
    inTangent: { x: 0, y: 0 },
    outTangent: { x: 0, y: 0 },
  };
}

// Sample a balance function over years 0..10 into a polyline.
function sample(f: (t: number) => number): PathVertex[] {
  const verts: PathVertex[] = [];
  const steps = 40;
  for (let i = 0; i <= steps; i++) {
    const t = (i / steps) * 10;
    const x = X0 + t * XSTEP;
    const y = Y0 - (f(t) - 100) * YSCALE;
    verts.push(vertex(x, y));
  }
  return verts;
}

