// Quadratic bezier sampled into straight segments.
function quad(
  p0: { x: number; y: number },
  p1: { x: number; y: number },
  p2: { x: number; y: number },
  n: number,
): PathVertex[] {
  const out: PathVertex[] = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const u = 1 - t;
    const x = u * u * p0.x + 2 * u * t * p1.x + t * t * p2.x;
    const y = u * u * p0.y + 2 * u * t * p1.y + t * t * p2.y;
    out.push({
      point: { x: Math.round(x * 100) / 100, y: Math.round(y * 100) / 100 },
      inTangent: { x: 0, y: 0 },
      outTangent: { x: 0, y: 0 },
    });
  }
  return out;
}

