import {
  ANIMATION_DOCUMENT_VERSION, assertValidAnimationDocument, withComputedRevision,
  base, constant, keyed, fill, stroke, trim, hex,
} from "@clayzo/animation/authoring";
import type { AnimationDocument, SceneNode, PathVertex } from "@clayzo/animation/authoring";

const OUT = { x1: 0.2, y1: 0.6, x2: 0.35, y2: 1 };
const ink = hex("#1F2A44"), blue = hex("#2E86E4"), grey = hex("#9A958A"), red = hex("#E4572E"), green = hex("#2E9E5B"), purple = hex("#7A4FD6");

const paper: SceneNode = { ...base("paper", { outTick: 1440, x: 600, y: 400 }), type: "rect", size: constant({ width: 1200, height: 800 }), cornerRadius: constant(0), style: { fill: fill(hex("#F7F5EF")) } };

const others: Record<string, SceneNode> = {};
const order: string[] = [];
const add = (n: SceneNode, id: string) => { others[id] = n; order.push(id); };

const layerX = [300, 600, 900];
const counts = [3, 4, 2];
const colors = [blue, purple, green];
const names = ["input", "layer", "output"];
const ys = counts.map(c => Array.from({ length: c }, (_, i) => 400 + (i - (c - 1) / 2) * 140));
const v = (x: number, y: number): PathVertex => ({ point: { x, y }, inTangent: { x: 0, y: 0 }, outTangent: { x: 0, y: 0 } });

// edges first (drawn under nodes)
let e = 0;
for (let l = 0; l < 2; l++) {
  const t0 = 160 + l * 200;
  for (const ya of ys[l]) for (const yb of ys[l + 1]) {
    const id = `edge${e}`;
    const w = 2 + ((e * 7) % 5) * 1.6;
    add({
      ...base(id, { outTick: 1440 }), type: "path",
      path: constant({ contours: [{ closed: false, vertices: [v(layerX[l], ya), v(layerX[l + 1], yb)] }] }),
      style: { stroke: stroke(grey, w) },
      operators: [trim(`${id}t`, { end: keyed(`${id}e`, [[t0, 0, OUT], [t0 + 200, 1]]) })],
    } as SceneNode, id);
    e++;
  }
}

// nodes
for (let l = 0; l < 3; l++) {
  const t0 = l * 80;
  ys[l].forEach((y, i) => {
    const id = `n${l}_${i}`;
    add({
      ...base(id, { outTick: 1440, x: layerX[l], y, scale: keyed(`${id}s`, [[t0, { x: 0, y: 0, z: 1 }, OUT], [t0 + 160, { x: 1, y: 1, z: 1 }]]) }),
      type: "ellipse", size: constant({ width: 70, height: 70 }), style: { fill: fill(colors[l]) },
    } as SceneNode, id);
  });
  const tid = `lab${l}`;
  add({
    ...base(tid, { outTick: 1440, x: layerX[l] - 100, y: 660, opacity: keyed(`${tid}o`, [[t0, 0, OUT], [t0 + 160, 1]]) }),
    type: "text",
    runs: constant([{ text: names[l], fontAssetId: "inter", fontSize: 34, fontWeight: 600, letterSpacing: 0, lineHeight: 41, color: ink }]),
    box: { width: 200, height: 41 }, wrap: "none", align: "center", verticalAlign: "top",
  } as SceneNode, tid);
}

// number pulses travelling through layers
const paths = [[0, 1, 0], [2, 3, 1]];
paths.forEach((p, k) => {
  const id = `pulse${k}`;
  const s = 360 + k * 40;
  add({
    ...base(id, {
      outTick: 1440,
      position: keyed(`${id}p`, [
        [s, { x: layerX[0], y: ys[0][p[0]], z: 0 }, "linear"],
        [s + 120, { x: layerX[1], y: ys[1][p[1]], z: 0 }, "linear"],
        [s + 240, { x: layerX[2], y: ys[2][p[2]], z: 0 }],
      ]),
      opacity: keyed(`${id}o`, [[s - 4, 0, "hold"], [s, 1]]),
    }),
    type: "ellipse", size: constant({ width: 30, height: 30 }), style: { fill: fill(red) },
  } as SceneNode, id);
});

