import {
  ANIMATION_DOCUMENT_VERSION,
  assertValidAnimationDocument,
  withComputedRevision,
  base,
  constant,
  keyed,
  fill,
  stroke,
  trim,
  hex,
} from "@clayzo/animation/authoring";
import type { AnimationDocument, SceneNode, PathVertex } from "@clayzo/animation/authoring";

const OUT = { x1: 0.2, y1: 0.6, x2: 0.35, y2: 1 };

type Pt = { x: number; y: number };

const paper: SceneNode = {
  ...base("paper", { outTick: 1440, x: 600, y: 400 }),
  type: "rect",
  size: constant({ width: 1200, height: 800 }),
  cornerRadius: constant(0),
  style: { fill: fill(hex("#F7F5EF")) },
} as SceneNode;

// Neuron: a circle that grows in from nothing.
function neuron(id: string, p: Pt, t0: number, dur: number, color: string): SceneNode {
  return {
    ...base(id, {
      outTick: 1440,
      x: p.x,
      y: p.y,
      scale: keyed(`${id}-scale`, [
        [t0, { x: 0, y: 0, z: 1 }, OUT],
        [t0 + dur, { x: 1, y: 1, z: 1 }],
      ]),
    }),
    type: "ellipse",
    size: constant({ width: 72, height: 72 }),
    style: { fill: fill(hex(color)) },
  } as SceneNode;
}

// Connection: a line that draws itself on between two neurons.
function connection(id: string, a: Pt, b: Pt, t0: number, dur: number): SceneNode {
  const v = (p: Pt): PathVertex => ({
    point: { x: p.x, y: p.y },
    inTangent: { x: 0, y: 0 },
    outTangent: { x: 0, y: 0 },
  });
  return {
    ...base(id, { outTick: 1440, x: 0, y: 0 }),
    type: "path",
    path: constant({ contours: [{ closed: false, vertices: [v(a), v(b)] }] }),
    style: { stroke: stroke(hex("#9A958A"), 4) },
    operators: [
      trim(`${id}-trim`, {
        end: keyed(`${id}-end`, [
          [t0, 0, OUT],
          [t0 + dur, 1],
        ]),
      }),
    ],
  } as SceneNode;
}

function label(id: string, text: string, cx: number, y: number): SceneNode {
  return {
    ...base(id, { outTick: 1440, x: cx - 100, y }),
    type: "text",
    runs: constant([
      {
        text,
        fontAssetId: "inter",
        fontSize: 34,
        fontWeight: 600,
        letterSpacing: 0,
        lineHeight: 41,
        color: hex("#1F2A44"),
      },
    ]),
    box: { width: 200, height: 41 },
    wrap: "none",
    align: "center",
    verticalAlign: "top",
  } as SceneNode;
}

// Layout: three columns of neurons.
const inputs: Pt[] = [
  { x: 300, y: 280 },
  { x: 300, y: 400 },
  { x: 300, y: 520 },
];
const hidden: Pt[] = [
  { x: 600, y: 240 },
  { x: 600, y: 340 },
  { x: 600, y: 440 },
  { x: 600, y: 540 },
];
const outputs: Pt[] = [
  { x: 900, y: 330 },
  { x: 900, y: 470 },
];

const edges: SceneNode[] = [];
const neurons: SceneNode[] = [];

// Layer 1 neurons grow in first (0 - 96 ticks).
inputs.forEach((p, i) => neurons.push(neuron(`in-${i}`, p, 0, 96, "#2E86E4")));

// Input -> hidden connections draw on (96 - 240).
let e = 0;
inputs.forEach((a, i) =>
  hidden.forEach((b, j) => {
    edges.push(connection(`e1-${e++}`, a, b, 96 + (i + j) * 4, 120));
  })
);

// Hidden layer neurons (240 - 336).
hidden.forEach((p, i) => neurons.push(neuron(`hid-${i}`, p, 240, 96, "#7A4FD6")));

// Hidden -> output connections draw on (336 - 480).
e = 0;
hidden.forEach((a, i) =>
  outputs.forEach((b, j) => {
    edges.push(connection(`e2-${e++}`, a, b, 336 + (i + j) * 4, 120));
  })
);

// Output neurons (480 - 576).
outputs.forEach((p, i) => neurons.push(neuron(`out-${i}`, p, 480, 96, "#2E9E5B")));

// Static layer labels below each column.
const labels: SceneNode[] = [
  label("lbl-in", "input", 300, 610),
  label("lbl-hid", "layer", 600, 610),
  label("lbl-out", "output", 900, 610),
];

const others: SceneNode[] = [...edges, ...neurons, ...labels];
const nodes: Record<string, SceneNode> = { paper };
for (const n of others) {
  nodes[(n as { id: string }).id] = n;
}

const doc: AnimationDocument = withComputedRevision({
  version: ANIMATION_DOCUMENT_VERSION,
  id: "visual",
  name: "visual",
  canvas: { width: 1200, height: 800, pixelAspectRatio: 1, backgroundColor: hex("#F7F5EF") },
  timing: {
    ticksPerSecond: 240,
    frameRate: { numerator: 60, denominator: 1 },
    durationTicks: 1440,
    displayStartTick: 0,
  },
  assets: {
    inter: { id: "inter", type: "font", uri: "/fonts/Inter-SemiBold.otf", family: "Inter", style: "normal", weight: 600 },
  },
  rootCompositionId: "main",
  components: {},
  compositions: {
    main: {
      id: "main",
      name: "Main",
      width: 1200,
      height: 800,
      durationTicks: 1440,
      nodes,
      rootNodeIds: ["paper", ...others.map((n) => (n as { id: string }).id)],
    },
  },
  markers: [],
  design: { tokens: { looping: false } },
  capabilities: { required: [], optional: [], unsupportedPolicy: "warn" },
} as unknown as AnimationDocument);

assertValidAnimationDocument(doc);
export default doc;
